record.field:
if record.partner_id.property_product_pricelist.id == 1:

    if record.x_crm_lead_line_ids:

        new_pricelist = env['product.pricelist'].create({
                'name': record.partner_id.name + " Pricelist test",
            })

        record.partner_id.write({"property_product_pricelist": new_pricelist.id})

        for line in record.x_crm_lead_line_ids:

            if line.x_type_selected == "Wholesale":
                line_price = line.x_price_wholesale
            elif line.x_type_selected == "By bottle":
                line_price = line.x_price_by_bottle
            elif line.x_type_selected == "Pouring":
                line_price = line.x_price_pouring
            else:
                line_price = 0

            if line_price > 0:

                env['product.pricelist.item'].create({
                        'pricelist_id': new_pricelist.id,
                        'applied_on': "1_product",
                        'product_tmpl_id': line.x_product_template_id.id,
                        'compute_price': "fixed",
                        'fixed_price': line_price,
                        'x_type': line.x_type_selected
                    })

else:

    raise UserError("This customer already has a custom pricelist!")

if record.partner_id.property_product_pricelist.id != 1:

    if record.crm_lead_line_ids:

        pricelist = record.partner_id.property_product_pricelist
        changed_lines = 0

        for line in record.crm_lead_line_ids:

            if line.type_selected == "Wholesale":
                line_price = line.price_wholesale
            elif line.type_selected == "By bottle":
                line_price = line.price_by_bottle
            elif line.type_selected == "Pouring":
                line_price = line.price_pouring
            else:
                line_price = 0

            if line_price > 0:

                existing_line = env['product.pricelist.item'].search([
                        ['pricelist_id', '=', pricelist.id],
                        ['product_tmpl_id', '=', line.product_template_id.id]
                        # ['fixed_price', '!=', line_price]
                    ])

                if existing_line:

                    if existing_line.fixed_price != line_price:

                        existing_line.write({
                                'fixed_price': line_price,
                                'goja_type': line.type_selected
                            })

                        changed_lines = changed_lines + 1

                else:

                    env['product.pricelist.item'].create({
                            'pricelist_id': pricelist.id,
                            'applied_on': "1_product",
                            'product_tmpl_id': line.product_template_id.id,
                            'compute_price': "fixed",
                            'fixed_price': line_price,
                            'goja_type': line.type_selected
                        })

                changed_lines = changed_lines + 1

        if changed_lines == 0:

            raise UserError("Nothing to update!")

else:

  raise UserError("This customer doesn't have a custom pricelist yet!")
